def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    special = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 7]
    if not special:
        return g

    r0 = min(r for r, c in special)
    c0 = min(c for r, c in special)
    shape = [(r-r0, c-c0) for r, c in special]

    for r in range(h):
        for c in range(w):
            cells = [(r+dr, c+dc) for dr, dc in shape]
            if all(0 <= rr < h and 0 <= cc < w and g[rr][cc] == 0
                   for rr, cc in cells):
                for rr, cc in cells:
                    g[rr][cc] = 7
    return g
